INSERT INTO public.scraper_sources (id, source_name, society, base_url, default_event_type, pagination_type, pagination_template, max_pages_hint, detail_is_multipage, active, extraction_instructions) VALUES
  (124, 'BSIR Events', 'BSIR', 'https://www.bsir.org/events/', 'mixed', 'single_page', NULL, 1, FALSE, TRUE, 'The /events/ hub is an index of ~13 event-series pages, not a dated list. Each series page holds the current year''s event as prose with the date in a sentence (ordinal days, weekday lists, often no year); some series have one level of sub-pages (IR Juniors -> NIRS/RiiSE, Webinars -> Upcoming webinars). The extractor crawls hub -> series -> sub-pages, takes the first non-deadline date line per page and fees from the page''s Register link (BSIR page or the CIRSE meeting site).'),
  (125, 'BMFMS Events', 'BMFMS', 'https://www.bmfms.org.uk/professionals/events', 'mixed', 'page_query', NULL, 1, FALSE, TRUE, 'Server-rendered calendar shows one year at a time as date_row rows (dates, title link, location); the extractor reads the current view plus the next two /date/<YYYY>/ pages. Rows are BMFMS, RCOG and third-party meetings. Detail pages are thin (date, place, prose); fees are on the external organiser site linked from ''Further details'' / ''Book online''.'),
  (126, 'BTS Education and Events', 'BTS', 'https://www.brit-thoracic.org.uk/education-and-events/', 'mixed', 'single_page', NULL, 1, FALSE, TRUE, 'Four server-rendered listings merged: short-course carousel cards, Winter/Summer meeting pages found from the hub (fees on /booking-rates/), the ''Upcoming webinars'' bullet list and the third-party ''Other respiratory courses'' table. Future meetings (next 18 months) come from the meeting-dates page. Course pages have a Fees block.'),
  (127, 'BSR Conferences, Courses and Webinars', 'BSR', 'https://www.rheumatology.org.uk/events-learning/conferences', 'mixed', 'single_page', NULL, 1, FALSE, TRUE, 'DNN site; three server-rendered listing modules (conferences, courses, webinars) whose div.article blocks hold title, link and a date footer (''Loading more'' is vestigial, TotalCount equals the blocks present). Stale or missing card dates (Annual Conference, undated webinar) are re-read from the detail page''s Date line; on-demand courses are skipped. Detail pages: Date / Venue / CPD labels plus a Members / Non-members pricing tab (ex VAT).'),
  (128, 'BAPM Meetings and Events', 'BAPM', 'https://www.bapm.org/pages/190-meetings-and-events', 'mixed', 'single_page', NULL, 1, FALSE, TRUE, 'Single Hubble-CMS page of div.teaser cards (title link, one-line intro such as ''A two day in person event'', start date + time). No pagination. Event pages give Date:/Location: lines and a ''More details''/''Book now'' link; BAPM''s own conference registers on a public CFS/EventsAir page whose fee list is parsed. Mixed BAPM and external events.'),
  (129, 'SBNS Event Calendar', 'SBNS', 'https://www.sbns.org.uk/event-calendar.html', 'mixed', 'single_page', NULL, 1, FALSE, TRUE, 'Preside/Eventfolio site; the calendar lists every upcoming event as article.eventfolio-calendar-event (date range, title link, type badge, city, CPD, Free/External badges); filters and result counter are JS-only and there is no pagination. Detail pages have an event-header block (date, venue lines), a ticket-price widget and a Book Now link to the organiser. Flagship meeting fees are in a PDF on a sub-page.')
